```python
class Vehicle:
    def __init__(self, make, model, year):
        self.make = make
        self.model = model
        self.year = year

    def honk(self):
        print('Honk honk!')

    def __str__(self):
        return '{} {} {}'.format(self.year, self.make, self.model)


class Car(Vehicle):
    def __init__(self, make, model, year, num_doors = 4):
        super().__init__(make, model, year)
        self.num_doors = num_doors

    def honk(self):
        super().honk()
        print('Beep beep!')

    def __str__(self):
        return super().__str__() + ' with {} doors'.format(self.num_doors)


class FlyingCar(Car):
    def __init__(self, make, model, year, num_doors = 4, num_wings = 2):
        super().__init__(make, model, year, num_doors)
        self.num_wings = num_wings

    def fly(self):
        print('Weee, we are flying!')

    def honk(self):
        super().honk()
        print('Neowww!')

    def __str__(self):
        return super().__str__() + ' and {} wings'.format(self.num_wings)
